mapper.select:
select study_date, seconds, article_seconds from learning_study_record
 where user_id = #{userId} and study_date between #{start} and #{end}
 order by study_date

select ifnull(sum(greatest(seconds - article_seconds, 0)), 0)
  from learning_study_record
 where user_id = #{userId}

select count(*) from learning_points_watch
 where user_id = #{userId} and target_type = 'post' and watched_seconds >= 30
   and award_date between #{start} and #{end}
